static int open_dchannel ( struct l1oip * hc , struct dchannel * dch , struct channel_req * rq ) { if ( debug & DEBUG_HW_OPEN ) { printk ( KERN_DEBUG "%s: dev(%d) open from %p\n" , __func__ , dch -> dev . id , __builtin_return_address ( 0 ) ) ; } if ( ( dch -> dev . D . protocol != ISDN_P_NONE ) && ( dch -> dev . D . protocol != rq -> protocol ) ) { if ( debug & DEBUG_HW_OPEN ) { printk ( KERN_WARNING "%s: change protocol %x to %x\n" , __func__ , dch -> dev . D . protocol , rq -> protocol ) ; } } if ( dch -> dev . D . protocol != rq -> protocol ) { dch -> dev . D . protocol = rq -> protocol ; } if ( test_bit ( FLG_ACTIVE , & dch -> Flags ) ) { _queue_data ( & dch -> dev . D , PH_ACTIVATE_IND , MISDN_ID_ANY , 0 , NULL , GFP_KERNEL ) ; } rq -> ch = & dch -> dev . D ; if ( ! try_module_get ( THIS_MODULE ) ) { printk ( KERN_WARNING "%s:cannot get module\n" , __func__ ) ; } return 0 ; } 